import { Button, Table } from 'antd';
import React from 'react'

function GenericTable({columns,data,title}) {
        // Add rowClassName for alternate striping
    const rowClassName = (record, index) =>
        index % 2 === 0 ? 'bg-gray-50' : 'bg-white';
  return (
        <div className="p-8 bg-gradient-to-br from-white via-gray-100 to-gray-200 rounded-2xl shadow-xl">
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center gap-4">
                        <h2 className="text-3xl font-extrabold text-gray-800 tracking-tight">{title}</h2>
                        <span className="text-gray-500 text-lg bg-gray-100 px-3 py-1 rounded-full">
                            {data.length} items
                        </span>
                    </div>
                    <Button
                        type="primary"
                        className="!bg-blue-600 !border-blue-600 !rounded-md !px-9 !py-6 !text-base !font-semibold hover:!bg-blue-400 transition"
                    >
                        Create New
                    </Button>
                </div>
                <Table
                    columns={columns}
                    dataSource={data}
                    pagination={false}
                    className="antd-table-custom"
                    rowClassName={rowClassName}
                    bordered
                />
            
            
                <style>
                    {`
                    .antd-table-custom .ant-table {
                        border-radius: 1rem;
                        overflow: hidden;
                        font-size: 1rem;
                    }
                    .antd-table-custom .ant-table-thead > tr > th {
                        background: linear-gradient(90deg, #f3f4f6 0%, #e5e7eb 100%);
                        font-weight: 700;
                        color: #374151;
                        border-bottom: 2px solid #e5e7eb;
                        padding: 16px;
                    }
                    .antd-table-custom .ant-table-tbody > tr > td {
                        padding: 16px;
                        font-size: 1rem;
                        color: #4b5563;
                    }
                    .antd-table-custom .ant-table-tbody > tr.bg-gray-50 > td {
                        background-color: #f9fafb !important;
                    }
                    .antd-table-custom .ant-table-tbody > tr.bg-white > td {
                        background-color: #fff !important;
                    }
                    .antd-table-custom .ant-table-tbody > tr:hover > td {
                        background: #e0e7ff !important;
                        transition: background 0.2s;
                    }
                    `}
                </style>
            </div>
  )
}

export default GenericTable